from pathlib import Path

path=Path('baseball-game.html')
text=path.read_text(encoding='utf-8')
lines=text.splitlines()

css="""
/* ===== V8 interactive pitching mode ===== */
.pitch-mode-panel{position:absolute;left:10px;right:10px;bottom:8px;z-index:27;background:rgba(3,18,20,.90);border:1px solid rgba(255,255,255,.16);border-radius:15px;padding:9px 10px;backdrop-filter:blur(7px);box-shadow:0 8px 24px #0007}.pitch-mode-panel.hidden{display:none!important}.pitch-mode-top{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:7px;font-size:11px;color:#b9cbc7}.pitch-mode-top strong{color:#ffe079;font-size:13px}.pitch-types{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:5px}.pitch-type{border:1px solid #3b5c5d;background:#0d3032;color:#dfe9e7;border-radius:10px;padding:7px 3px;font-size:10px;font-weight:900;min-height:38px}.pitch-type.active{background:#ffd052;color:#493500;border-color:#ffd052;box-shadow:0 0 0 2px #ffd05222}.pitch-type:disabled{opacity:.35}.pitch-help{text-align:center;font-size:10px;color:#9db4af;margin-top:6px}.control.pitch-action{background:linear-gradient(#7ee7b0,#43bb7b);color:#073b24;font-size:20px}.scene.user-pitching .zone{border-color:#75e5aa;background:rgba(71,210,137,.035);box-shadow:0 0 14px #52d98b22}.scene.user-pitching .aim{border-color:#7dffba;box-shadow:0 0 10px #62e99c99}.scene.user-pitching .aim:before,.scene.user-pitching .aim:after{background:#7dffba}.scene.user-pitching .batterCard{border-color:#ffffff2f}.scene.user-pitching .pitcher{filter:drop-shadow(0 7px 4px rgba(0,0,0,.35)) drop-shadow(0 0 6px rgba(100,240,170,.16))}
@media(max-width:620px){.pitch-mode-panel{left:6px;right:6px;bottom:5px;padding:7px 8px}.pitch-types{grid-template-columns:repeat(3,minmax(0,1fr))}.pitch-type{min-height:34px;padding:5px 2px}.scene.user-pitching .batterCard{max-width:62vw}.scene.user-pitching .hud{max-width:42vw}}
""".strip()
if '/* ===== V8 interactive pitching mode ===== */' not in text:
    text=text.replace('/* ===== V6 full baseball systems ===== */',css+'\n/* ===== V6 full baseball systems ===== */',1)

old_footer='<footer class="controls"><button id="menuBtn" class="control">結束／選單</button><button id="tacticsBtn" class="control strategy">戰術</button><button id="swingBtn" class="control" disabled>揮棒！</button></footer>'
new_footer='<footer class="controls"><button id="menuBtn" class="control">結束／選單</button><button id="tacticsBtn" class="control strategy">戰術</button><button id="swingBtn" class="control" disabled>揮棒！</button><button id="userPitchBtn" class="control pitch-action hidden">投球！</button></footer>'
if old_footer in text:text=text.replace(old_footer,new_footer,1)

hud='<div class="hud"><div id="pitchInfo">等待投球</div><span id="pitcherGameInfo" class="pitcherPill">投手 —</span><div style="color:#a9c0bb;margin-top:3px">拖曳九宮格瞄準・按揮棒</div></div>'
panel=hud+'\n    <div id="pitchModePanel" class="pitch-mode-panel hidden"><div class="pitch-mode-top"><strong id="userPitcherLabel">你的投手</strong><span id="cpuBatterLabel">對手打者</span></div><div id="pitchTypeButtons" class="pitch-types"></div><div class="pitch-help">先選球種 → 拖曳九宮格瞄準 → 按「投球！」</div></div>'
if 'id="pitchModePanel"' not in text and hud in text:text=text.replace(hud,panel,1)

# refresh after structural edits
lines=text.splitlines()

# Add state variables.
for i,line in enumerate(lines):
    if line.startswith("let userPitcher=null,cpuPitcher=null") and 'halfMode' not in line:
        lines[i]=line+"\nlet halfMode='bat',cpuBatIndex=0,selectedUserPitch='FF';"
        break

new_update="""function updateBoard(){if(!opponent||!lineup.length)return;$('cpuShort').textContent=teams[opponent].short;$('cpuScore').textContent=cpuScore;$('userScore').textContent=userScore;$('inningText').textContent=inning+'局'+(halfMode==='pitch'?'上':'下');$('situation').textContent=outs+'人出局';qsa('.lamp.b').forEach((e,i)=>e.classList.toggle('on',i<balls));qsa('.lamp.s').forEach((e,i)=>e.classList.toggle('on',i<strikes));qsa('.lamp.o').forEach((e,i)=>e.classList.toggle('on',i<outs));[$('base1'),$('base2'),$('base3')].forEach((e,i)=>e.classList.toggle('runner',!!bases[i]));if(halfMode==='pitch'){const order=cpuBattingOrder(),cur=order[cpuBatIndex%order.length],n1=order[(cpuBatIndex+1)%order.length],n2=order[(cpuBatIndex+2)%order.length],s=cur?.stats||{},r=cur?gameRatings(cur):{contact:0,power:0,speed:0};$('orderText').textContent='對手第 '+((cpuBatIndex%9)+1)+' 棒・打者';$('currentBatter').textContent=cur?.name||'—';$('batterTeam').textContent=cur?.teamName||teams[opponent].name;$('batterRealStats').textContent=cur?`AVG ${rate(s.AVG)}・OBP ${rate(s.OBP)}・SLG ${rate(s.SLG)}・OPS ${rate(s.OPS)}`:'AVG —・OBP —・SLG —・OPS —';$('batterGameRating').textContent=`CON ${r.contact}・PWR ${r.power}・SPD ${r.speed}`;$('nextBatters').textContent='後面：'+(n1?.name||'—')+'、'+(n2?.name||'—');const bc=teamPalette[opponent]||'#c33434';$('batter').querySelector('.torso').style.background=`linear-gradient(90deg,${bc} 0 68%,#20252a 69%)`;if(userPitcher){const pr=currentPitcherRatings(userPitcher),fat=pitcherFatigue(userPitcher),pc=teamPalette[userPitcher.player.teamKey]||'#f2f1ec';$('pitcher').querySelector('.body').style.background=`linear-gradient(${pc},#d7d8d4)`;$('pitcherGameInfo').textContent=`你投球 ${userPitcher.player.name}｜${userPitcher.pitches}球｜V${pr.velo} C${pr.control} B${pr.break}${fat>.55?'｜疲勞':''}`;$('pitcherGameInfo').classList.toggle('pitch-fatigue',fat>.55)}}else{const cur=currentPlayer(),n1=lineup[(batIndex+1)%9],n2=lineup[(batIndex+2)%9],s=cur.stats,r=gameRatings(cur);$('orderText').textContent='第 '+((batIndex%9)+1)+' 棒・'+(positionMap[playerId(cur)]||'—');$('currentBatter').textContent=cur.name;$('batterTeam').textContent=cur.teamName;$('batterRealStats').textContent=s?`AVG ${rate(s.AVG)}・OBP ${rate(s.OBP)}・SLG ${rate(s.SLG)}・OPS ${rate(s.OPS)}`:'AVG —・OBP —・SLG —・OPS —';$('batterGameRating').textContent=`CON ${r.contact}・PWR ${r.power}・SPD ${r.speed}`;$('nextBatters').textContent='後面：'+n1.name+'、'+n2.name;const bc=teamPalette[cur.teamKey]||'#e78928';$('batter').querySelector('.torso').style.background=`linear-gradient(90deg,${bc} 0 68%,#20252a 69%)`;if(cpuPitcher){const pr=currentPitcherRatings(cpuPitcher),fat=pitcherFatigue(cpuPitcher),pc=teamPalette[cpuPitcher.player.teamKey]||'#f2f1ec';$('pitcher').querySelector('.body').style.background=`linear-gradient(${pc},#d7d8d4)`;$('pitcherGameInfo').textContent=`投手 ${cpuPitcher.player.name}｜${cpuPitcher.pitches}球｜V${pr.velo} C${pr.control} B${pr.break}${fat>.55?'｜疲勞':''}`;$('pitcherGameInfo').classList.toggle('pitch-fatigue',fat>.55)}}}"""
new_intro="""function showIntro(){clearTimeout(introTimer);const p=halfMode==='pitch'?currentCpuBatter():currentPlayer(),s=p?.stats||{};if(!p)return;$('introName').textContent=p.name;$('introTeam').textContent=halfMode==='pitch'?p.teamName+'・對手打者':p.teamName+'・'+(positionMap[playerId(p)]||'DH');$('introAvg').textContent=rate(s.AVG);$('introSlg').textContent=rate(s.SLG);$('introOps').textContent=rate(s.OPS);$('introCard').classList.remove('hidden');introTimer=setTimeout(()=>$('introCard').classList.add('hidden'),1050)}"""
new_start="""function startGame(){initAudio();$('setupApp').classList.add('hidden');$('gameApp').classList.remove('hidden');playing=true;inning=1;userScore=0;cpuScore=0;balls=strikes=outs=0;bases=[null,null,null];batIndex=0;cpuBatIndex=0;aimX=aimY=.5;$('aim').style.left='50%';$('aim').style.top='50%';usedBatters=new Set(lineup.map(playerId));usedPitchers=new Set();substitutions=[];cpuPitcherUsed=new Set();const sp=players.find(p=>playerId(p)===config.starterPitcherId)||pitcherCandidates()[0];userPitcher=makePitcherState(sp);usedPitchers.add(playerId(sp));substitutions.push(`投手群：先發 ${sp.name}｜中繼 ${(config.middlePitcherIds||[]).map(id=>players.find(p=>playerId(p)===id)?.name).filter(Boolean).join('、')}｜終結 ${players.find(p=>playerId(p)===config.closerPitcherId)?.name||'—'}`);selectCpuPitcher(true);lineup.forEach(p=>ensurePlayer(p).G++);saveDb();const park=currentPark();$('scoreboardBig').textContent=park.name.toUpperCase();$('scene').classList.toggle('indoor',!!park.roof);startPitchHalf(true)}"""
new_endhalf="""function endHalf(){clearMotion();outs=0;balls=strikes=0;bases=[null,null,null];if(halfMode==='pitch'){userPitcher.innings++;if(inning===9&&userScore>cpuScore)return endGame('比賽勝利！');return startBatHalf()}if(inning>=9){if(userScore!==cpuScore)return endGame(userScore>cpuScore?'比賽勝利！':'比賽敗北');return endGame('九局和局')}inning++;startPitchHalf(false)}"""

for i,line in enumerate(lines):
    if line.startswith('function updateBoard(){'): lines[i]=new_update
    elif line.startswith('function showIntro(){'): lines[i]=new_intro
    elif line.startswith('function startGame(){'): lines[i]=new_start
    elif line.startswith('function endHalf(){'): lines[i]=new_endhalf
    elif line.startswith('function schedulePitch('): lines[i]=line.replace("if(!playing||outs>=3)return;","if(!playing||halfMode!=='bat'||outs>=3)return;")
    elif line.startswith('function throwPitch(){'): lines[i]=line.replace("if(!playing)return;","if(!playing||halfMode!=='bat')return;",1)
    elif line.startswith('function swing(){'): lines[i]=line.replace("function swing(){if(!playing||!pitching)return;","function swing(){if(halfMode!=='bat'||!playing||!pitching)return;",1)
    elif line.startswith('function animatePitch(now){'):
        lines[i]=line.replace("takePitch();return","if(halfMode==='pitch')resolveCpuPitch();else takePitch();return",1)
    elif line.startswith('function endGame(title){'):
        lines[i]=line.replace("$('swingBtn').disabled=true;","$('swingBtn').disabled=true;$('userPitchBtn').disabled=true;",1)
    elif line.startswith("$('pitchChangeBtn').onclick="):
        lines[i]=line.replace("renderTactics();updateBoard()","renderTactics();updateBoard();if(halfMode==='pitch')renderUserPitchControls()",1)

# Insert pitching-half functions before schedulePitch.
insert_at=next((i for i,l in enumerate(lines) if l.startswith('function schedulePitch(')),None)
if insert_at is None: raise SystemExit('schedulePitch anchor missing')
if not any('function cpuBattingOrder()' in l for l in lines):
    funcs=r"""
function cpuBattingOrder(){const a=offensePlayers(opponent);const eligible=a.filter(p=>(num(p.stats?.PA)||0)>=20);const src=eligible.length>=9?eligible:a;return [...src].sort((x,y)=>{const xp=num(x.stats?.PA)||0,yp=num(y.stats?.PA)||0,xo=num(x.stats?.OPS)||0,yo=num(y.stats?.OPS)||0;return(yo*0.72+Math.min(yp,350)/350*.28)-(xo*0.72+Math.min(xp,350)/350*.28)}).slice(0,9)}
function currentCpuBatter(){const a=cpuBattingOrder();return a[cpuBatIndex%Math.max(1,a.length)]}
function setHalfMode(mode){halfMode=mode;const pitch=mode==='pitch';$('scene').classList.toggle('user-pitching',pitch);$('pitchModePanel').classList.toggle('hidden',!pitch);$('userPitchBtn').classList.toggle('hidden',!pitch);$('swingBtn').classList.toggle('hidden',pitch);$('swingBtn').disabled=pitch;$('userPitchBtn').disabled=!pitch;$('pitchInfo').textContent=pitch?'選球種並瞄準':'準備投球';if(pitch)renderUserPitchControls()}
function renderUserPitchControls(){if(!userPitcher)return;const pr=currentPitcherRatings(userPitcher),rep=pr.repertoire||['FF'];if(!rep.includes(selectedUserPitch))selectedUserPitch=rep[0];$('pitchTypeButtons').innerHTML=Object.entries(basePitchTypes).map(([code,p])=>`<button class="pitch-type ${selectedUserPitch===code?'active':''}" data-user-pitch="${code}" ${rep.includes(code)?'':'disabled'}>${p.n}</button>`).join('');qsa('[data-user-pitch]').forEach(b=>b.onclick=()=>{selectedUserPitch=b.dataset.userPitch;renderUserPitchControls()});$('userPitcherLabel').textContent=`${userPitcher.player.name}・${userPitcher.role}`;$('cpuBatterLabel').textContent=`${currentCpuBatter()?.name||'—'}｜${userPitcher.pitches} 球`;const fat=pitcherFatigue(userPitcher);$('userPitchBtn').disabled=pitching||fat>=1;$('userPitchBtn').textContent=fat>.82?'投球（疲勞）':'投球！'}
function startPitchHalf(first=false){clearMotion();setHalfMode('pitch');outs=0;balls=strikes=0;bases=[null,null,null];aimX=aimY=.5;$('aim').style.left='50%';$('aim').style.top='50%';updateBoard();showIntro();setMsg(inning+'局上','你來投球・'+userPitcher.player.name+(first?' 先發登板':''),'');renderUserPitchControls();$('userPitchBtn').disabled=false}
function startBatHalf(){clearMotion();setHalfMode('bat');outs=0;balls=strikes=0;bases=[null,null,null];aimX=aimY=.5;$('aim').style.left='50%';$('aim').style.top='50%';updateBoard();setMsg(inning+'局下','輪到你進攻','');showIntro();schedulePitch(900)}
function userThrowPitch(){if(!playing||halfMode!=='pitch'||pitching||!userPitcher)return;const pr=currentPitcherRatings(userPitcher),fat=pitcherFatigue(userPitcher),code=selectedUserPitch,pt=basePitchTypes[code]||basePitchTypes.FF;lastPitch=pt.n;const fast=136+pr.velo*.22-fat*5;lastSpeed=Math.round(fast+pt.delta+rand(-1.6,1.6));pitchDuration=clamp(720+(150-lastSpeed)*3.5,680,930);const miss=clamp((100-pr.control)/290+fat*.13,.018,.22);pitchTargetX=clamp(aimX+rand(-miss,miss),-.30,1.30);pitchTargetY=clamp(aimY+rand(-miss,miss),-.30,1.30);const breakScale=.65+pr.break/100;pitchCurve=(pitchTargetX<.5?-1:1)*pt.c*breakScale;pitchDrop=pt.drop*breakScale;pitchStart=0;pitching=true;userPitcher.pitches++;$('userPitchBtn').disabled=true;$('tacticsBtn').disabled=true;$('pitchInfo').textContent=lastPitch+' '+lastSpeed+' km/h';const pitcher=$('pitcher');pitcher.classList.remove('windup','release');void pitcher.offsetWidth;pitcher.classList.add('windup');sfx('pitch');timer=setTimeout(()=>{pitcher.classList.remove('windup');pitcher.classList.add('release');pitchStart=performance.now();$('ball').style.display='block';$('ballShadow').style.display='block';raf=requestAnimationFrame(animatePitch)},430)}
function cpuTakeOrSwing(batter){const r=gameRatings(batter),inZone=strikeLoc(),edge=Math.min(Math.abs(pitchTargetX-.5),Math.abs(pitchTargetY-.5)),eye=r.eye||65;let swingProb=inZone?clamp(.70+(strikes===2?.14:0)-edge*.08,.58,.94):clamp(.30-(eye-60)*.003+(strikes===2?.09:0),.10,.48);return Math.random()<swingProb}
function cpuBattedMetrics(batter,q){const r=gameRatings(batter),pow=(r.power-55)/45;const exit=clamp(62+q*42+pow*8+rand(-5,5),48,116),launch=clamp(rand(-10,34)+pow*7+(q-.55)*12,-25,48),spray=clamp(rand(-43,43)+(pitchTargetX-.5)*10,-50,50);let distance;if(launch<=2)distance=clamp(35+exit*1.15+launch*1.5,25,175);else{const v=exit*.44704,rad=launch*Math.PI/180;distance=(v*v*Math.sin(2*rad)/9.81)*3.28084*.68*currentPark().carry+rand(-10,10);distance=clamp(distance,45,485)}const hang=launch>5?clamp(.6+launch*.06+(exit-78)*.01,.7,4.6):clamp(.45+distance/200,.45,1.5),x=clamp(50+spray/50*35,10,90),y=clamp(80-(distance/500)*69,8,76);return{exit,launch,spray,distance,hang,targetX:x,targetY:y,fence:fenceDistance(spray)}}
function cpuBallOutcome(batter,q,b){const s=batter.stats||{},avg=num(s.AVG)??.255,slg=num(s.SLG)??.390,hr=num(s.HR)||0,pa=Math.max(1,num(s.PA)||1),def=defenseRating();let hit=clamp(avg+(q-.55)*.18-(def-68)*.0022,.12,.47);if(Math.random()>hit)return{result:'OUT',label:b.launch<7?'內野滾地出局':b.launch>24?'外野高飛球接殺':'平飛球出局'};const hrp=clamp((hr/pa)*2.1+Math.max(0,slg-.43)*.12+Math.max(0,q-.72)*.08,.005,.17);if(b.launch>13&&b.launch<42&&b.distance>b.fence*.94&&Math.random()<Math.max(hrp,.08))return{result:'HR',label:'對手全壘打'};const extra=clamp((slg-avg)*.60+.04,.08,.30),r=Math.random();if(r<extra*.10&&gameRatings(batter).speed>75)return{result:'3B',label:'對手三壘安打'};if(r<extra)return{result:'2B',label:'對手二壘安打'};return{result:'1B',label:'對手安打'}}
function resolveCpuPitch(){if(halfMode!=='pitch')return;const batter=currentCpuBatter();if(!batter)return endHalf();const swing=cpuTakeOrSwing(batter);if(!swing){sfx('catch');if(strikeLoc()){strikes++;setMsg('好球！',`${batter.name} 沒出棒・${lastPitch} ${lastSpeed} km/h`,'good');if(strikes>=3)return completeCpuPA('K','三振！')}else{balls++;setMsg('壞球',`${batter.name} 忍住沒揮`,'');if(balls>=4)return completeCpuPA('BB','四壞保送')}updateBoard();renderUserPitchControls();$('userPitchBtn').disabled=false;return}const batterEl=$('batter'),bat=$('bat');batterEl.classList.add('swing');bat.classList.add('swing');setTimeout(()=>{batterEl.classList.remove('swing');bat.classList.remove('swing')},240);const pr=currentPitcherRatings(userPitcher),r=gameRatings(batter),locPenalty=strikeLoc()?Math.hypot(pitchTargetX-.5,pitchTargetY-.5)*.12:.16;const q=clamp(.54+(r.contact-65)*.006-(pr.velo-70)*.003-(pr.break-70)*.003-locPenalty+rand(-.22,.22),0,1);if(q<.25){strikes++;setMsg('揮空！',`${batter.name} 沒跟上 ${lastPitch}`,'good');sfx('out');if(strikes>=3)return completeCpuPA('K','揮空三振！');updateBoard();renderUserPitchControls();$('userPitchBtn').disabled=false;return}if(Math.random()<clamp(.23-q*.10,.08,.22)){if(strikes<2)strikes++;setMsg('界外球',`${batter.name} 擊成界外`,'');updateBoard();renderUserPitchControls();$('userPitchBtn').disabled=false;return}const b=cpuBattedMetrics(batter,q),o=cpuBallOutcome(batter,q,b);lastBattedBall=b;sfx('bat');showCpuHitThen(o.result,o.label,b,batter)}
function showCpuHitThen(result,label,b,batter){resetHitCamera();const cam=$('hitCam'),ball=$('flyball'),shadow=$('hitBallShadow'),splash=$('resultSplash'),target=[b.targetX,b.targetY],isHr=result==='HR',ground=b.launch<7,dur=isHr?1750:ground?900:clamp(b.hang*650,900,1600);cam.classList.remove('hidden');cam.classList.toggle('hrMode',isHr);cam.style.setProperty('--batter-team',teamPalette[opponent]||'#c33434');cam.style.setProperty('--defense-team','#f4f3ed');$('metricEV').textContent=Math.round(b.exit)+' mph';$('metricLA').textContent=Math.round(b.launch)+'°';$('metricDist').textContent=Math.round(b.distance)+' ft';splash.textContent=result==='OUT'?label:result==='HR'?'HOME RUN!':label;const fielder=nearestHitFielder(target[0],target[1]);if(fielder&&!isHr){const rect=fielder.getBoundingClientRect(),crect=cam.getBoundingClientRect(),sx=(rect.left+rect.width/2-crect.left)/crect.width*100,sy=(rect.top+rect.height/2-crect.top)/crect.height*100;fielder.animate([{left:sx+'%',top:sy+'%'},{left:target[0]+'%',top:(target[1]+3)+'%'}],{duration:Math.min(900,dur*.72),easing:'cubic-bezier(.2,.7,.2,1)',fill:'forwards'})}const frames=ground?[{left:'50%',top:'78%',transform:'scale(1)'},{left:target[0]+'%',top:target[1]+'%',transform:'scale(.65)'}]:[{left:'50%',top:'78%',transform:'scale(1)'},{left:((target[0]+50)/2)+'%',top:((target[1]+78)/2-13)+'%',transform:'scale(.78)'},{left:target[0]+'%',top:target[1]+'%',transform:'scale(.62)'}];ball.animate(frames,{duration:dur,easing:'cubic-bezier(.2,.7,.2,1)',fill:'forwards'});if(shadow)shadow.animate([{left:'50%',top:'82%',opacity:.45},{left:target[0]+'%',top:(target[1]+5)+'%',opacity:.24}],{duration:dur,fill:'forwards'});if(result==='OUT'&&fielder)setTimeout(()=>{const flash=$('catchFlash');flash.style.left=target[0]+'%';flash.style.top=target[1]+'%';flash.style.opacity='1';flash.classList.remove('pop');void flash.offsetWidth;flash.classList.add('pop');sfx('catch')},Math.min(760,dur*.72));if(isHr){sfx('hr');setTimeout(()=>sfx('cheer'),700)}else if(result!=='OUT')sfx('hit');else sfx('out');setTimeout(()=>{cam.classList.add('hidden');resetHitCamera();completeCpuPA(result,label)},isHr?2100:Math.max(1150,dur+180))}
function cpuAdvance(result,batter){let runs=0;const pre=[...bases],br=runnerObj(batter,cpuBatIndex%9);if(result==='BB'){if(pre[0]&&pre[1]&&pre[2])runs++;bases=[br,pre[1]||pre[0],pre[2]||(pre[1]&&pre[0])]}else if(result==='1B'){const n=[br,null,null];if(pre[2])runs++;if(pre[1])Math.random()<.72?runs++:n[2]=pre[1];if(pre[0])Math.random()<.30?n[2]=pre[0]:n[1]=pre[0];bases=n}else if(result==='2B'){const n=[null,br,null];if(pre[2])runs++;if(pre[1])runs++;if(pre[0])Math.random()<.58?runs++:n[2]=pre[0];bases=n}else if(result==='3B'){runs+=pre.filter(Boolean).length;bases=[null,null,br]}else if(result==='HR'){runs=1+pre.filter(Boolean).length;bases=[null,null,null]}return runs}
function completeCpuPA(result,label=''){const batter=currentCpuBatter();let runs=0;if(result==='K'||result==='OUT')outs++;else runs=cpuAdvance(result,batter);cpuScore+=runs;cpuBatIndex=(cpuBatIndex+1)%Math.max(1,cpuBattingOrder().length);balls=strikes=0;setMsg(label||result,(runs?runs+' 分・':'')+batter.name,result==='K'||result==='OUT'?'good':'bad');updateBoard();if(outs>=3)return endHalf();showIntro();renderUserPitchControls();$('userPitchBtn').disabled=false}
$('userPitchBtn').addEventListener('click',userThrowPitch);
""".strip().splitlines()
    lines[insert_at:insert_at]=funcs

# Pitching tactics: only pitching change is relevant on defense.
for i,line in enumerate(lines):
    if line.startswith('function renderTactics(){') and "halfMode==='pitch'" not in line:
        lines[i]=line+"\n$('pinchHitBtn').disabled=halfMode==='pitch';$('pinchRunBtn').disabled=halfMode==='pitch';if(halfMode==='pitch')$('tacticStatus').textContent='目前由你投球；此時可使用換投。';"
        break

# Hide pitching UI when returning to setup.
for i,line in enumerate(lines):
    if "function returnToSetup(){" in line and "pitchModePanel" not in line:
        lines[i]=line.replace("$('gameApp').classList.add('hidden');","$('gameApp').classList.add('hidden');$('pitchModePanel').classList.add('hidden');$('userPitchBtn').classList.add('hidden');$('swingBtn').classList.remove('hidden');",1)
        break

text='\n'.join(lines)+'\n'
path.write_text(text,encoding='utf-8')
print('Added interactive pitching half-innings.')
